        /// * `RS256`, `RS384`, `RS512` - RSA with SHA-256/384/512
        /// * `ES256`, `ES384`, `ES512` - ECDSA with SHA-256/384/512
        /// * `PS256`, `PS384`, `PS512` - RSA-PSS with SHA-256/384/512
        /// </summary>
        public InputList<string> SupportedAlgorithms
        {
            get => _supportedAlgorithms ?? (_supportedAlgorithms = new InputList<string>());
            set => _supportedAlgorithms = value;
        }

        /// <summary>
        /// If true, use JWKS URI for key validation; if false, use static public keys. Defaults to `True`. When set to true, `JwksUri` is required. When set to false, `PublicKeys` is required.
        /// </summary>
        [Input("useJwks")]
        public Input<bool>? UseJwks { get; set; }

        /// <summary>
        /// The claim to use as the user identifier. Defaults to `Sub`. This determines which JWT claim is used to identify the user.
        /// </summary>
        [Input("userClaim")]
        public Input<string>? UserClaim { get; set; }

        public OauthResourceServerConfigProfileState()
        {
        }
        public static new OauthResourceServerConfigProfileState Empty => new OauthResourceServerConfigProfileState();
    }
}
